# co-change analysis: files that always change together want to be one abstraction
commits = [
    {'a.py', 'b.py', 'c.py'}, {'a.py', 'b.py', 'c.py'},
    {'a.py', 'b.py'}, {'d.py'},
]
from collections import Counter
pairs = Counter()
for c in commits:
    for x in c:
        for y in c:
            if x < y:
                pairs[(x, y)] += 1
print('co-change counts:', dict(pairs))
