import ast

RULES = []

class Smells(ast.NodeVisitor):
    def visit_FunctionDef(self, node):
        defaults = node.args.defaults
        for d in defaults:
            if isinstance(d, (ast.List, ast.Dict, ast.Set)):
                RULES.append((node.lineno, 'mutable default argument'))
        # deeply nested?
        depth = 0
        for n in ast.walk(node):
            if isinstance(n, (ast.If, ast.For, ast.While)):
                depth = max(depth, 1)
        self.generic_visit(node)
    def visit_ExceptHandler(self, node):
        if len(node.body) == 1 and isinstance(node.body[0], ast.Pass):
            RULES.append((node.lineno, 'empty except block (swallows errors)'))

src = 'def f(xs=[]):\n    pass\ntry:\n    g()\nexcept Exception:\n    pass\n'
Smells().visit(ast.parse(src))
for line, msg in RULES:
    print('line %d: %s' % (line, msg))

