# (x, y) travels together through 4 signatures: it wants to be a Point
from collections import Counter
sigs = [
    ('move', ('x', 'y')), ('draw', ('x', 'y', 'color')),
    ('dist', ('x', 'y', 'x2', 'y2')), ('scale', ('x', 'y', 'f')),
]
pairs = Counter()
for _, params in sigs:
    for i in range(len(params)):
        for j in range(i + 1, len(params)):
            pairs[tuple(sorted((params[i], params[j])))] += 1
print('co-occurring pairs:', dict(pairs))
